import { Component, OnInit } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ApiService } from 'src/app/services/tnvn/services/api.service';
import { IonicStorageService } from 'src/app/services/tnvn/services/ionic-storage/ionic-storage.service';
import { AlertService } from "src/app/services/tnvn/services/alert.service";
import { PostService } from "src/app/services/tnvn/services/post.service";
import { ModalController, AlertController } from "@ionic/angular";
import { ActivatedRoute, Router } from "@angular/router";
import { EmimodalComponent } from "src/app/components/emimodal/emimodal.component";
import { NetworkService } from "src/app/services/tnvn/services/network.service";
import { LoadingService } from "src/app/services/tnvn/services/loading.service";
@Component({
  selector: 'app-observation-end',
  templateUrl: './observation-end.component.html',
  styleUrls: ['./observation-end.component.scss'],
})
export class ObservationEndComponent implements OnInit {


  public storeDetail: any;
  public teacherDetail: any;
  public schoolDetail: any;
  public goToHomepage: any;
  public DoneNote: any;
  public classDetail: any;
  progressValue:number;       
  public languageType:any;
  public congratulations:any;
  public successfullyCompleted:any;
  public Observation:any;
  public done:any;
  public networkInfo: any;
  public class:any;
  schoolId: any;
  schoolDetails: any;
  pageFlow: any;
  classList: any[] = [];
  storedFinalData:any=[];
  check: boolean = true;
  actualValueList: any[] = [];
  divisionType: any;
  observetheClass:any;
  observeQuestion:any;
  observeQuestionOne:any;  
  listedDistrict: boolean = false;
  listedEduDistrict: boolean = false;
  listedBlock: boolean = false;
  listedZone: boolean = false;
  listedTotalTeachers: boolean = false;
  listedTotalStudents: boolean = false;
  correctedDistrict: string = "";
  correctedEduDistrict: string = "";
  correctedBlock: string = "";
  correctedZone: string = "";
  correctedTotalTeachers: string = "";
  correctedTotalStudents: string = "";
  presentValue: any;
  correctedClass: any[] = [];
  isOpen: boolean = false;
  actualDetails: any;
  Yes: any;
  No: any;
  vacancies: any;
  masterApiResponse: any;
  teacherSanctionedValue: any;
  teachersAvailableValue: any;
  teachersDeputationSameSchoolValue: any;
  teachersDeputationOtherSchoolValue: any;
  teachersOnLongLeaveValue: any; 
  public Verification: any;
  public school: any;
  public anotherclass: any;
  public primary: any;
  public secondary: any;
  public middle: any;
  public district: any;
  public educationalDistrict: any;
  public block: any;
  public zone: any;
  public teachersTotal: any;
  public studentsTotal: any;
  public boysTotal: any;
  public girlsTotal: any;  
  public back: any;
  public next: any;
  public giveCheck: any;
  public enterVacancy: any;
  public vacanciesTotal: any;
  public selectedClass:any;
  public selectedSection:any;
  public teacherSanctioned: string;
  public teachersAvailable: string;
  public teachersDeputationSameSchool: string;
  public teachersDeputationOtherSchool: string;
  public teachersOnLongLeave: string;

  public teacherSanctionedRequired: string;
  public teachersAvailableRequired: string;
  public teachersDeputationSameSchoolRequired: string;
  public teachersDeputationOtherSchoolRequired: string;
  public teachersOnLongLeaveRequired: string;

  public submitted: boolean = false;              
       
  constructor(public ionicStore: IonicStorageService,
    private _apiService: ApiService,
    public _alertService: AlertService,    
    public alertController: AlertController,
    public loading: LoadingService,
    public _router: Router,
    public networkService: NetworkService,        
    private _translate: TranslateService) { }

  ngOnInit() {
    this.progressValue = 100;
    this.appLanguage();

    this.teacherDetail = JSON.parse(localStorage.getItem('teacherInfo'));
    this.schoolDetail = JSON.parse(localStorage.getItem('schoolInfo'));
    this.classDetail = JSON.parse(localStorage.getItem('classInfo'));
    this.selectedSection = localStorage.getItem("selectedSection");    
    this.ionicStore.getOffStorage().then((response) => {
      if (response) {
        this.masterApiResponse = response;        
      }     
    this.ionicStore.getStoreData()
      .then((response) => {
        this.storeDetail = response;        
        this.ionicStore.setStoreData(this.storeDetail);
        localStorage.setItem("storedDetails",JSON.stringify(this.storeDetail))
        // if(!this.storeDetail) {
        //   this.createPage();
        // }                                
        // if (this.storeDetail.pages.pageData[13] == undefined || this.storeDetail.pages.pageData[13] == null) {
        // }
      });
    });

  }

  async showAlert(alertInfo = "", message = "") {
    const alert = await this.alertController.create({
      header: "",
      cssClass: "my-custom-class",
      message: this.DoneNote,
      buttons: [{ 
          text: "ok",
          handler: () => {            
        } }],
    });
    await alert.present();
  }  
  appLanguage(){
    this._apiService.languageInfo.subscribe((data:any) => {
      this.languageType = data;      
      this._translate.use(this.languageType);
      this._initialiseTranslation();      
 });
}

  _initialiseTranslation(): void {
    
    this._translate.get('Observation').subscribe((res: string) => {
      this.Observation = res; 
    });
    this._translate.get('goToHomepage').subscribe((res: string) => {
      this.goToHomepage = res; 
    });    
    this._translate.get('DoneNote').subscribe((res: string) => {
      this.DoneNote = res; 
    });    
    this._translate.get('successfullyCompleted').subscribe((res: string) => {
      this.successfullyCompleted = res; 
    });
    this._translate.get('congratulations').subscribe((res: string) => {
      this.congratulations = res; 
    });
    this._translate.get('class').subscribe((res: string) => {
      this.class = res; 
    });
    this._translate.get('done').subscribe((res: string) => {
      this.done = res; 
    });
    
   
  }
  
  createPage = () => {
    let apiData = {
      pageNo: '14',
      pageName: 'Observation_complete_percentage',
      apiResponse: {
        records: {
        }
      },
    };
    this.storeDetail.pages.pageData[13] = apiData;
    this.storeDetail.pages.currentProgress = this.progressValue;
    this.ionicStore.setStoreData(this.storeDetail);    
  }
  finalSubmit = async() => {  
        localStorage.removeItem("classInfo");        
        localStorage.removeItem("schoolInfo");
        localStorage.removeItem("teacherInfo");
        localStorage.removeItem("routingList");
        localStorage.removeItem("classroom_section_status");
        localStorage.removeItem("metho_section_status");
        localStorage.removeItem("stu_attend_section_status");
        localStorage.removeItem("assessment_section_status");
        // localStorage.removeItem("omr_rand_stu_section_status");
        // localStorage.removeItem("omr_scanner_section_status");
        // localStorage.removeItem("omr_student_section_status");
        localStorage.removeItem("notebook_section_status");
        localStorage.removeItem("pre_obs_qns_section_status");
        localStorage.removeItem("obs_report_section_status");
        localStorage.removeItem("hod_inspect_section_status");
        localStorage.removeItem("emidata_section_status");
        // localStorage.removeItem("emiverify_section_status");      
        this.ionicStore.removeOffStorage();
    this._router.navigate(["/tnvntabs/page-route/dashboardc"]);    
  };
}
